function cloudhost247_ovh_config(){return array('name'=>'CloudHost247 OVH','description'=>'Independent authenticated OVH catalog, mapping, provisioning and synchronization.','version'=>'1.4.0','author'=>'CloudHost247','language'=>'english','fields'=>array());}
function cloudhost247_ovh_activate(){try{$a=(new MigrationRunner())->run('cloudhost247_ovh',array(new OvhInitialMigration(),new OvhOperationalMigration(),new OvhParityMigration(),new OvhDiscoveryMigration(),new HostingProductMigration(),new \CloudHost247\Ovh\Migrations\PricingEvidenceMigration(),new \CloudHost247\Ovh\Migrations\CentralCredentialMigration()));return array('status'=>'success','description'=>'OVH integration installed: '.($a?implode(', ',$a):'already current'));}catch(\Throwable$e){return array('status'=>'error','description'=>$e->getMessage());}}
